import{_ as a,o as e,c as t,a2 as n}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"ko/reference/cli.md","filePath":"ko/reference/cli.md","lastUpdated":1793550481000}'),i={name:"ko/reference/cli.md"};function o(p,s,d,l,c,h){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>이 문서는 <code>mcp-lens</code>의 모든 명령을 정확한 플래그와 기본값까지 함께 정리한다. <code>--help</code>를 다시 실행하지 않아도 여기서 바로 찾을 수 있다. 처음부터 끝까지 한 번 돌려보려면 <a href="/MCPLens/ko/quick-start">빠른 시작</a>을 보고, 리포트 열이 무엇을 뜻하는지는 <a href="/MCPLens/ko/guide/reading-reports">리포트 읽기</a>를 본다.</p><p>모든 명령은 같은 진입점을 공유한다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens &lt;command&gt; [options]</span></span></code></pre></div><p><code>scan</code>과 <code>auth</code>만 데이터베이스에 쓰기 때문에, 이 둘만 writer lease를 잡고 VS Code 확장과 경합한다. <code>report</code>는 데이터베이스를 열지만 부수적인 로그 백필 외에는 쓰지 않는다. 확장이 lease를 쥐고 있으면 그 저장을 조용히 건너뛰고도 동일한 리포트를 읽기 전용으로 그대로 출력한다. writer lease가 왜 존재하는지는 <a href="/MCPLens/ko/concepts/how-it-works">동작 원리</a>를 본다.</p><h2 id="report" tabindex="-1">report <a class="header-anchor" href="#report" aria-label="Permalink to &quot;report&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens report [--days &lt;n&gt;] [--format &lt;f&gt;]</span></span></code></pre></div><p>비용 × 사용량 매트릭스를 출력한다. 스캔된 모든 툴의 정의 토큰 비용을 실제 호출 횟수와 나란히 놓고, 행마다 권장 조치를 붙인다. 이것이 기본 명령이라서 플레인 <code>mcp-lens</code>도 같은 동작을 한다.</p><table tabindex="0"><thead><tr><th>옵션</th><th>기본값</th><th>의미</th></tr></thead><tbody><tr><td><code>--days &lt;n&gt;</code></td><td><code>30</code></td><td>최근 <code>n</code>일치만 집계한다. 0보다 큰 숫자여야 한다.</td></tr><tr><td><code>--format &lt;f&gt;</code></td><td><code>table</code></td><td>출력 형식: <code>table</code>, <code>ai</code>, <code>json</code> 중 하나.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> table</span></span></code></pre></div><p>표에는 열이 11개 있다. 블록을 짧게 유지하려고 실제 행 중 3개만 발췌했지만, 열은 전부 실제 그대로다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server          tool                     defTokens  calls  respTokens  loaded/sessions  errorRate  errorTokens  action  confidence  reason</span></span>
<span class="line"><span>--------------  -----------------------  ---------  -----  ----------  ---------------  ---------  -----------  ------  ----------  ------------------------------------------------------------------------------------------------------------------------------------------</span></span>
<span class="line"><span>web-search      web-search_place_search  17251      0      0           0/533            -          0            remove  medium      definition 17,251 tokens, 0 calls. small savings, but cleans up the search space. 98 sessions/3d observed, confirmed with more observation</span></span>
<span class="line"><span>knowledge-base  knowledge-base-search    1809       10     124         5/533            0%         0            keep    high        called 10 times</span></span>
<span class="line"><span>weather-tools   get_weather              74         4      83          3/533            0%         0            keep    high        called 4 times</span></span>
<span class="line"><span></span></span>
<span class="line"><span>savings: potential=61893 actual=26839 saved=35054</span></span>
<span class="line"><span>(0 session files backfilled)</span></span></code></pre></div><p><code>--format ai</code>는 같은 데이터를 Markdown으로 출력하되, 행별 reason 템플릿을 중복 제거해서 표 위쪽 &quot;Row reason templates&quot; 절로 모아준다. 이것이 <code>/lens-audit</code> 슬래시 명령이 소비하는 형식이며, 어떤 툴을 끌지 LLM과 채팅하며 판단시키고 싶을 때 붙여넣기 좋은 형태이기도 하다.</p><h2 id="scan" tabindex="-1">scan <a class="header-anchor" href="#scan" aria-label="Permalink to &quot;scan&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens scan [--config &lt;path&gt;]</span></span></code></pre></div><p>설정된 모든 MCP 서버에 잠깐 연결해서 <code>tools/list</code>를 호출하고, 각 툴의 정의 토큰 수를 기록한다. LLM 토큰을 전혀 쓰지 않고, 클라이언트 설정 파일을 절대 편집하지 않는다.</p><table tabindex="0"><thead><tr><th>옵션</th><th>기본값</th><th>의미</th></tr></thead><tbody><tr><td><code>--config &lt;path&gt;</code></td><td>감지된 모든 클라이언트 설정</td><td>모든 클라이언트 설정을 자동 탐색하는 대신, 이 설정 파일 하나만 읽고 스캔한다.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span></span></code></pre></div><p><code>discovered:</code> 줄은 설정 소스별로(<code>claude-user</code>, <code>claude-project</code>, <code>codex</code>, <code>gemini</code>) 몇 개의 서버가 발견됐는지 <code>·</code>로 이어서 보여준다. 아래 예시는 실제 형식에 예시 수치를 넣은 것이다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>discovered: claude-user 2 · codex 1</span></span>
<span class="line"><span>- web-search: 9 tools, 26198 tokens</span></span>
<span class="line"><span>- knowledge-base: 15 tools, 24157 tokens</span></span></code></pre></div><p><code>scan</code>은 데이터베이스에 쓰기 때문에 writer lease를 잡는다. VS Code 확장이 현재 lease를 쥐고 있으면, 확장의 관측치를 덮어쓰는 대신 메시지를 출력하고 0이 아닌 상태 코드로 종료한다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The VS Code extension is writing the MCP Lens DB, so this command cannot run right now.</span></span>
<span class="line"><span>Close the extension window (or the other running mcp-lens) and try again. It may also clear on its own shortly.</span></span></code></pre></div><h2 id="auth" tabindex="-1">auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;auth&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens auth &lt;serverName&gt; [--clear]</span></span></code></pre></div><p>HTTP MCP 서버 하나에 대해 OAuth 로그인을 실행한 뒤, 그 서버만 다시 스캔한다. <code>tools/list</code>가 성공하기 전에 로그인이 필요한 서버에 쓴다.</p><table tabindex="0"><thead><tr><th>옵션</th><th>기본값</th><th>의미</th></tr></thead><tbody><tr><td><code>--clear</code></td><td>off</td><td>로그인하는 대신 <code>&lt;serverName&gt;</code>에 저장된 인증 정보를 삭제한다.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github: login complete, 12 tools · 3410 tokens</span></span></code></pre></div><p><code>scan</code>과 마찬가지로 <code>auth</code>도 데이터베이스에 쓰면서 writer lease를 잡지만, 최종 저장 시점 근처에서만 그렇다. 브라우저 로그인 자체는 lease를 요청하기 전에 일어나므로, 로그인이 느려도 확장을 막지 않는다. 서버가 자동 클라이언트 등록을 거부하면(예를 들어 GitHub나 Figma의 원격 MCP 서버), 대신 OAuth 클라이언트 id를 설정할 설정 키나 개인 액세스 토큰용 헤더를 명령이 출력해 준다.</p><h2 id="hooks-status" tabindex="-1">hooks status <a class="header-anchor" href="#hooks-status" aria-label="Permalink to &quot;hooks status&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hooks status [--json]</span></span></code></pre></div><p>클라이언트별 훅 설치 상태를 보여준다. 훅 패키지가 설치됐는지, trust 상태가 승인됐는지 (Codex 전용), 번들된 러너가 있는지, 마지막으로 관측된 훅 이벤트, 아직 대기 중인 이벤트 수, 전체 health를 표시한다.</p><table tabindex="0"><thead><tr><th>옵션</th><th>기본값</th><th>의미</th></tr></thead><tbody><tr><td><code>--json</code></td><td>off</td><td>사람이 읽는 형식 대신 같은 데이터를 JSON으로 출력한다.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>아래 필드명과 구조는 실제다(클라이언트당 한 블록, <code>client / package / trust / runner / last event / pending / fallback / health</code>). 값은 예시일 뿐 실제로 캡처한 실행 결과가 아니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude Code</span></span>
<span class="line"><span>  package: installed</span></span>
<span class="line"><span>  trust: not-required</span></span>
<span class="line"><span>  runner: ready</span></span>
<span class="line"><span>  last event: &lt;ISO timestamp of the most recent inbox event, or &quot;none&quot;&gt;</span></span>
<span class="line"><span>  pending: 0</span></span>
<span class="line"><span>  fallback: unknown</span></span>
<span class="line"><span>  health: idle</span></span></code></pre></div><h2 id="hooks-doctor" tabindex="-1">hooks doctor <a class="header-anchor" href="#hooks-doctor" aria-label="Permalink to &quot;hooks doctor&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hooks doctor [client]</span></span></code></pre></div><p>훅 설정을 진단하고 발견 사항마다 한 줄씩, 가장 심각한 것부터 출력한다. 클라이언트 이름을 넘기면 그 클라이언트만 검사한다.</p><table tabindex="0"><thead><tr><th>인자</th><th>값</th></tr></thead><tbody><tr><td><code>client</code> (선택)</td><td><code>claude-code</code>, <code>codex</code>, <code>gemini-cli</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] codex codex-trust-unapproved: Codex hook trust is not approved; review it with /hooks.</span></span></code></pre></div><h2 id="hook-capture" tabindex="-1">hook capture <a class="header-anchor" href="#hook-capture" aria-label="Permalink to &quot;hook capture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hook capture --client &lt;c&gt;</span></span></code></pre></div><p>이것은 사람이 직접 실행하는 명령이 아니라 훅 런타임의 진입점이다. Claude Code, Codex, Gemini CLI가 lifecycle hook으로 이것을 호출하며, 훅 payload를 stdin으로 흘려보낸다. payload를 디코드해서 관측 결과를 <code>~/.mcplens/inbox</code>에 큐잉하고, payload가 잘못됐거나 <code>--client</code>가 없거나 인식되지 않는 경우에도 항상 stdout에 <code>{}</code>를 출력하고 exit 0으로 끝난다. 이 fail-open 계약은 여기 버그가 있어도 코딩 세션을 절대 막지 않게 하기 위한 것이다.</p>`,45)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
